"""Cinematic community overview and dedicated Clubhouse presentation."""
hero_alts.update({'clubhouse':'Stone and timber Clubhouse and full-size pool in a tropical mountain garden','landscape':'Private mountain homes among lush gardens and woodland'})
pages['vision.html']=('The vision',
 hero('landscape','The Mount Paradise vision','Room for yourself.<br><em>A place to belong.</em>','Private homes in the trees. A Clubhouse at the heart. A landscape that brings them together.')
 +f'''<section class="section feature" id="discover">{pic('interior','Warm teak and volcanic stone interior opening to lush gardens','Stone, timber and light · Architectural concept')}<div class="feature-copy"><p class="eyebrow">Rooted in the mountains</p><h2>Built around<br>what matters.</h2><p>Natural stone. Substantial timber. Deep verandas that draw life outdoors. The existing pilot inspires a family of homes shaped around gardens, privacy and time together.</p>{link('lodges.html','Explore cabins and lodges')}</div></section>
 <section class="section dark"><div class="section-heading"><div><p class="eyebrow">The shared heart</p><h2>Your place.<br>Our Clubhouse.</h2></div>{link('clubhouse.html','Step inside the Clubhouse')}</div>{pic('clubhouse','Proposed Clubhouse overlooking its swimming pool and mountain gardens','The Clubhouse · Phase 2 concept')}<p class="image-story">A morning swim, a game of tennis, a long lunch on the terrace. The Clubhouse and its garden pavilions bring dining, wellness, recreation and good company into the rhythm of mountain life.</p></section>
 <section class="section feature">{pic('mountain-cabin','A compact stone and timber cabin in its own fern garden','Mountain Cabin · Architectural concept')}<div class="feature-copy"><p class="eyebrow">A home at your scale</p><h2>Small escape.<br>Generous life.</h2><p>Begin with a Mountain Cabin, or explore the Retreat, Family, Reserve and Estate lodges. Each has a private relationship with the garden and a shared connection to the wider sanctuary.</p>{link('lodge-tiers.html','Compare the collection')}</div></section>
 <section class="section plan-preview" id="private-sanctuary"><div class="section-heading"><div><p class="eyebrow">Within the gates</p><h2>Take the scenic<br>way home.</h2></div></div>{pic('terrace','A sheltered mountain veranda surrounded by abundant planting','A slower mountain rhythm · Lifestyle concept')}<div class="thirds">{row('Arrive','A private approach','A dedicated gated entrance and controlled arrival are planned for residents and their guests.')}{row('Explore','Through the gardens','Stone roads for golf carts and places to walk connect private homes with the Clubhouse.')}{row('Return','Your own quiet corner','A porch, a veranda or a garden terrace. A personal place to pause at the end of the day.')}</div></section>
 <section class="section" id="community-lodge"><div class="split"><h2>One vision.<br>Three chapters.</h2><div><p>The built pilot is the starting point. Phase 2 extends the community across 10 hectares, with a future expansion opportunity of 20+ hectares in Phase 3.</p>{link('land.html','Explore the land')}<br><span id="club-membership">{link('clubhouse.html#membership','Explore Club Membership')}</span></div></div></section>''')
pages['clubhouse.html']=('The Clubhouse',
 hero('clubhouse','The Clubhouse / Mount Paradise','The heart of<br><em>the mountain.</em>','A favorite table. A mountain terrace. An occasion worth remembering.')
 +f'''<section class="section intro" id="discover"><p class="eyebrow">The Clubhouse &amp; its gardens</p><div class="split"><h2>One beautiful place.<br>Many ways to belong.</h2><div class="prose"><p>The Clubhouse is envisioned as the social heart of Mount Paradise: restaurant, bar, café and lounges opening onto the pool and mountain terraces. A separate Spa Pavilion and Recreation Pavilion extend the experience through the gardens.</p></div></div><div class="club-index"><a href="#dining">Restaurant &amp; bar ↓</a><a href="#cafe">The café ↓</a><a href="#events">Private events ↓</a><a href="#recreation">Recreation ↓</a><a href="#spa">Spa &amp; baths ↓</a></div></section>
 <section class="section dark" id="dining"><div class="section-heading"><div><p class="eyebrow">The restaurant / Bar / Mountain patio</p><h2>A table with<br>a different outlook.</h2></div></div>{pic('clubhouse-restaurant','Stone and teak restaurant with a bar and open patio facing the mountains','The Clubhouse restaurant & mountain patio')}<div class="split image-copy"><div><h3>Inside, warmly gathered.</h3><p>The dining wing carries the stone pillars, exposed teak and sheltered roofline of the Clubhouse into an intimate restaurant. A polished bar offers a place to meet before dinner or settle into the evening.</p></div><div><h3>Outside, the whole mountain.</h3><p>On the mountain-facing side, the restaurant opens onto a generous patio. Long lunches, sunset drinks and candlelit dinners share an uninterrupted sense of the landscape.</p></div></div></section>
 <section class="section feature" id="cafe">{pic('terrace-calm','Relaxed cafe seating beneath teak eaves with coffee and mountain views','The café terrace')}<div class="feature-copy"><p class="eyebrow">Coffee / Conversation / A slower morning</p><h2>Take your<br>usual seat.</h2><p>A relaxed café corner with comfortable chairs, small tables and the quiet pleasure of a good view. Come for coffee and something fresh from the kitchen; stay for a book, a conversation or a second cup.</p><p>Green ferns, natural stone and warm timber keep the setting calm. The mountains provide the color.</p></div></section>
 <section class="section dark" id="events"><div class="section-heading"><div><p class="eyebrow">Weddings / Celebrations / Private gatherings</p><h2>Some evenings<br>deserve this setting.</h2></div></div>{pic('clubhouse-arrival','Valet welcoming elegantly dressed guests beside a silver sports car at the Clubhouse entrance','The Clubhouse arrival & valet drive')}<div class="split image-copy"><div><h3>An arrival of its own.</h3><p>A dedicated valet approach curves toward the sheltered Clubhouse entrance. Guests step from the car into a warm welcome, with an arrival sequence kept separate from the pool terraces and garden paths.</p></div><div><h3>A gathering to remember.</h3><p>The restaurant, lounges and mountain patio are envisioned for wedding receptions, elegant private dinners, milestone celebrations and high-end events. Spaces flow from welcome drinks to dinner and an evening beneath the eaves.</p></div></div></section>
 <section class="section" id="swim-play"><div class="section-heading"><div><p class="eyebrow">The pool garden</p><h2>A little movement.<br>A long exhale.</h2></div></div>{pic('clubhouse','Clubhouse and swimming pool framed by restrained green planting','The Clubhouse & pool terrace')}<p class="image-story">A full-size pool sits at the center of the shared gardens. Swim before breakfast, rest on the terrace, or follow the garden path toward the Recreation Pavilion.</p></section>
 <section class="section dark" id="recreation"><div class="section-heading"><div><p class="eyebrow">The Recreation Pavilion</p><h2>Room to move.<br>Space to play.</h2></div></div>{pic('recreation-pavilion','Separate stone and timber gym pavilion with an adjacent tennis court beyond the pool garden','The Recreation Pavilion / Gym & tennis')}<div class="split image-copy"><div><h3>A gym facing the gardens.</h3><p>A low, separate pavilion beyond the pool accommodates strength and cardio training, with wide glazing bringing the landscape into the workout. Its stone and timber architecture belongs to the same family as the Clubhouse.</p></div><div><h3>A court among the trees.</h3><p>The tennis court sits alongside the gym, connected by sheltered paths and green planting. Keeping active recreation together gives it room to breathe while preserving the atmosphere of the restaurant and lounges.</p></div></div></section>
 <section class="section feature" id="spa">{pic('clubhouse-spa','Stone bathing pools in a separate teak-roofed spa pavilion facing the mountain forest','The Spa Pavilion / Baths & restoration')}<div class="feature-copy"><p class="eyebrow">The Spa Pavilion / A quieter garden</p><h2>A world<br>of its own.</h2><p>Tucked into a quieter part of the gardens, the Spa Pavilion has its own roofline, bathing pools and treatment spaces. A short landscaped walk connects it to the Clubhouse.</p><p>Warm stone, open forest views and the sound of water create a setting apart from the energy of dining, events and sport.</p></div></section>
 <section class="section plan-preview" id="membership"><p class="eyebrow">The Mount Paradise Club</p><div class="split"><h2>Your private home.<br>A shared mountain life.</h2><div><p>The Clubhouse, Spa Pavilion and Recreation Pavilion form a connected family of places, linked by the pool garden and stone paths. Club Membership is envisioned around this shared world, close to the privacy of your own cabin or lodge.</p>{link('lodges.html','Find your mountain home')}</div></div></section>''')
# Put the Clubhouse on the homepage as a visual destination.
title,body=pages['index.html']
body+=f'''<section class="section feature">{pic('clubhouse','Cinematic Clubhouse and pool terrace surrounded by mountain gardens','The Clubhouse · Proposed architectural concept')}<div class="feature-copy"><p class="eyebrow">The shared heart of Mount Paradise</p><h2>Meet at<br>the Clubhouse.</h2><p>A swim, a match, a quiet hour at the spa. A favorite table and a familiar face. Explore the proposed social heart of the community.</p>{link('clubhouse.html','Discover the Clubhouse')}</div></section>'''
pages['index.html']=(title,body)
